code='''def transform(grid):
    n = len(grid)
    # Tile side equals the number of tile rows/columns; separators are one cell wide.
    s = next(k for k in range(1, n + 1) if k * (k + 1) - 1 == n)
    out = [row[:] for row in grid]
    motifs = []
    for i in range(s):
        for j in range(s):
            r0, c0 = i * (s + 1), j * (s + 1)
            block = [row[c0:c0+s] for row in grid[r0:r0+s]]
            if all(v != 3 for row in block for v in row) and any(v == 2 for row in block for v in row):
                motifs.append(tuple(tuple(row) for row in block))
    from collections import Counter
    motif = Counter(motifs).most_common(1)[0][0]
    # The motif is itself the occupancy map for the larger tile array.
    for i in range(s):
        for j in range(s):
            if motif[i][j] == 2:
                r0, c0 = i * (s + 1), j * (s + 1)
                for a in range(s):
                    for b in range(s):
                        value = motif[a][b]
                        if a == i and b == j and value == 2:
                            value = 8
                        out[r0+a][c0+b] = value
    for r in range(n):
        for c in range(n):
            if out[r][c] == 3:
                out[r][c] = 0
    return out
'''
